### Steps to reproduce

1. Create a Flutter Web application that embeds an HTML platform view using `HtmlElementView`.
2. In the host webpage (`web/index.html`), set `<html dir="rtl">` (or dynamically set `document.documentElement.setAttribute('dir', 'rtl')`)

### Expected results

platform view should render at its expected widget coordinates within the Flutter layout on screen

### Actual results

platform view renders off-screen to the far right

### Code sample

<details open><summary>Code sample</summary>

```dart
import 'dart:ui_web' as ui_web;

import 'package:flutter/material.dart';
import 'package:web/web.dart' as web;

void main() {
  ui_web.platformViewRegistry.registerViewFactory('sample-platform-view', (
    int viewId,
  ) {
    final element = web.HTMLDivElement();
    element.id = 'sample-view-$viewId';
    element.style.width = '100%';
    element.style.height = '100%';
    element.style.backgroundColor = '#4CAF50';
    element.style.color = 'white';
    element.style.display = 'flex';
    element.style.alignItems = 'center';
    element.style.justifyContent = 'center';
    element.style.fontWeight = 'bold';
    element.innerText = 'Platform View Box';
    return element;
  });

  runApp(const BugReproApp());
}

class BugReproApp extends StatefulWidget {
  const BugReproApp({super.key});

  @override
  State<BugReproApp> createState() => _BugReproAppState();
}

class _BugReproAppState extends State<BugReproApp> {
  bool _isRtl = true;

  @override
  void initState() {
    super.initState();
    _applyDirectionality();
  }

  void _applyDirectionality() {
    web.document.documentElement?.setAttribute('dir', _isRtl ? 'rtl' : 'ltr');
  }

  void _toggleDirectionality() {
    setState(() {
      _isRtl = !_isRtl;
      _applyDirectionality();
    });
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      home: Scaffold(
        appBar: AppBar(
          title: Text(
            'RTL Platform View Bug (Document dir="${_isRtl ? 'rtl' : 'ltr'}")',
          ),
          actions: [
            FilledButton.tonal(
              onPressed: _toggleDirectionality,
              child: Text(_isRtl ? 'Switch to LTR' : 'Switch to RTL'),
            ),
            const SizedBox(width: 16),
          ],
        ),
        body: Center(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                _isRtl
                    ? 'In RTL document: without fix, this box is pushed offscreen to the right ➔'
                    : 'In LTR document: this box renders centered properly.',
                style: const TextStyle(fontSize: 16),
              ),
              const SizedBox(height: 16),
              Container(
                width: 250,
                height: 250,
                decoration: BoxDecoration(
                  border: Border.all(color: Colors.red, width: 2),
                ),
                child: const HtmlElementView(viewType: 'sample-platform-view'),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

